interface Text { String render(); }

class Plain implements Text {
    public String render() { return "hi"; }
}

class Upper implements Text {          // wraps a Text and uppercases it
    private final Text inner;
    Upper(Text inner) { this.inner = inner; }
    public String render() { return inner.render().toUpperCase(); }
}

System.out.println(new Upper(new Plain()).render());

interface Report { String data(); }

class RealReport implements Report {
    public String data() {
        System.out.println("computing");
        return "R";
    }
}

class CachedReport implements Report {   // keeps the first result and reuses it
    private final Report real = new RealReport();
    private String cached;
    public String data() {
        if (cached == null) cached = real.data();
        return cached;
    }
}

Report r = new CachedReport();
System.out.println(r.data() + r.data());

