interface Text { String render(); }

class Plain implements Text {
    public String render() { return "a"; }
}

class Upper implements Text {              // uppercases what it wraps
    private final Text inner;
    Upper(Text inner) { this.inner = inner; }
    public String render() { return inner.render().toUpperCase(); }
}

class Cached implements Text {             // does the real call at most once
    private final Text inner;
    private String cached;
    Cached(Text inner) { this.inner = inner; }
    public String render() {
        if (cached == null) {
            System.out.println("real call");
            cached = inner.render();
        }
        return cached;
    }
}

Text t = new Cached(new Upper(new Plain()));
System.out.println(t.render() + t.render());

