interface Report { String data(); }

class RealReport implements Report {
    RealReport() { System.out.println("created"); }
    public String data() { return "x"; }
}

class Loud implements Report {                  // uppercases what it wraps
    private final Report inner;
    Loud(Report inner) { this.inner = inner; }
    public String data() { return inner.data().toUpperCase(); }
}

class Lazy implements Report {                  // builds its target on first use
    private Report real;
    public String data() {
        if (real == null) real = new Loud(new RealReport());
        return real.data();
    }
}

Report r = new Lazy();
System.out.println("start");
