interface Cache { String get(String key); }

class TtlDecorator implements Cache {
    private final Cache inner;
    TtlDecorator(Cache inner) { this.inner = inner; }

    public String get(String key) {
        if (expired(key)) return null;     // do not reach the real cache
        return inner.get(key);
    }
}
